WITH valid_departments AS (SELECT * FROM departments WHERE dept_name != 'Marketing' AND budget BETWEEN 1754000 AND 2381000 AND dept_name IN ('Marketing', 'Sales')), summary AS (SELECT CASE WHEN budget >= 3185000 THEN 'high' WHEN budget >= 1672000 THEN 'mid' ELSE 'low' END AS budget_bucket, SORT_ARRAY(COLLECT_SET(location)) AS location_list, ROUND(STDDEV(budget), 2) AS stddev_budget FROM valid_departments GROUP BY CASE WHEN budget >= 3185000 THEN 'high' WHEN budget >= 1672000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, location_list FROM summary WHERE stddev_budget < 49 ORDER BY budget_bucket DESC
